head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > getValue]<br/>Calendar 컴포넌트의 선택된 날짜값을 포맷이 적용되지 않은 문자열로 반환합니다.",
    "validation" : [
        "Calendar 컴포넌트의 선택된 날짜값을 포맷이 적용되지 않은 문자열(String)로 반환합니다. (구분자 없는 숫자 문자열)",
        "calendarValueType='yearMonth' 설정 시 'yyyyMM' 포맷의 6자리 숫자 문자열을 반환합니다. (예: '202503')",
        "calendarValueType='yearMonthDate' 설정 시 'yyyyMMdd' 포맷의 8자리 숫자 문자열을 반환합니다. (예: '20250315')",
        "calendarValueType='yearMonthDateHour' 설정 시 'yyyyMMddHH' 포맷의 10자리 숫자 문자열을 반환합니다. (예: '2025031514')",
        "calendarValueType='yearMonthDateTime' 설정 시 'yyyyMMddHHmm' 포맷의 12자리 숫자 문자열을 반환합니다. (예: '202503151430')",
        "calendarValueType='yearMonthDateTimeSec' 설정 시 'yyyyMMddHHmmSS' 포맷의 14자리 숫자 문자열을 반환합니다. (예: '20250315143025')",        
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // calendarValueType 별 자릿수에 맞춰 초기 선택 날짜 설정 (getValue 결과 확인용)
    // 기본 표시 날짜: 2025-11-11, 시/분/초는 gotoTime() 으로 별도 설정
    let valueType = target1.options.calendarValueType || 'yearMonthDate';
    target1.gotoCalendar('20251111');
    if (valueType === 'yearMonthDateHour') {
        target1.gotoTime(14, 0, 0);
    } else if (valueType === 'yearMonthDateTime') {
        target1.gotoTime(14, 30, 0);
    } else if (valueType === 'yearMonthDateTimeSec') {
        target1.gotoTime(14, 30, 25);
    }
}



// getValue() 반환값 출력
// validation: 선택된 날짜값을 포맷이 적용되지 않은 String 으로 반환 (calendarValueType 별 자릿수)
scwin.btn_getValue_onclick = function (e) {
    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 반환] '" + rtn + "'");
};
